-- ============================================================================
--  Tlemcen street network, from OpenStreetMap.
--
--  Loaded into the database rather than reverse-geocoded at runtime: street
--  names do not change between two requests, while an API call per cluster
--  would be rate-limited, slow, and would fail silently the day the service is
--  down. Here, naming a point is a spatial index lookup.
--
--  Regenerate from the pipeline project when OSM coverage improves.
-- ============================================================================

set search_path = public, extensions;

create table if not exists osm_roads (
  osm_id  bigint primary key,
  name    text,
  ref     text,
  highway text,
  geom    geography(LineString, 4326) not null
);
create index if not exists osm_roads_geom_idx on osm_roads using gist (geom);

create table if not exists osm_places (
  osm_id bigint primary key,
  name   text not null,
  place  text,
  geom   geography(Point, 4326) not null
);
create index if not exists osm_places_geom_idx on osm_places using gist (geom);

truncate osm_roads;
truncate osm_places;













analyze osm_roads;
analyze osm_places;
